def format_overview(practical):
    details = PRACTICAL_DETAILS[practical["notebook"]]
    steps = [step.strip().rstrip(".") for step in details["flow"].split(";") if step.strip()]
    lines = [f"{practical['title']}", f"Purpose: {practical['summary']}", "", "What the code covers:"]
    lines.extend(f"- {concept}." for concept in PRACTICAL_CONCEPTS[practical["notebook"]])
    lines.append("\nExecution order:")
    lines.extend(f"{i}. {step}." for i, step in enumerate(steps, 1))
    lines.extend(["\nInputs and required files:", f"- {details['inputs']}",
                  "\nWhat the notebook displays or prints:", f"- {details['outputs']}",
                  "\nPython dependencies:", f"- {details['dependencies']}"])
    if practical["dataset"]:
        lines.extend(["\nDataset selected by the launcher:", f"- {practical['dataset']} (you may choose another file with the same expected format)."])
    return "\n".join(lines)

