def uncomment_source(source):
    """Remove Python comments without touching # characters inside strings."""
    tokens = tokenize.generate_tokens(io.StringIO(source).readline)
    uncommented = tokenize.untokenize(token for token in tokens if token.type != tokenize.COMMENT)
    lines = []
    previous_blank = False
    for line in uncommented.splitlines():
        line = line.rstrip()
        blank = not line.strip()
        if blank and (not lines or previous_blank):
            continue
        lines.append(line)
        previous_blank = blank
    return "\n".join(lines).strip() + ("\n" if lines else "")

def prepare_notebook(nb, name):
    """Keep original cell order, strip comments, and split known monolithic cells."""
    breaks = CELL_BREAK_MARKERS.get(name, ())
    rebuilt = []
    for cell in nb.get("cells", []):
        if cell.get("cell_type") != "code":
            rebuilt.append(cell)
            continue
        original = "".join(cell.get("source", []))
        sections = []
        current = []
        for line in original.splitlines(keepends=True):
            if any(marker in line for marker in breaks):
                if "".join(current).strip(): sections.append("".join(current))
                current = []
                if line.lstrip().startswith("#"):
                    continue
            current.append(line)
        if "".join(current).strip(): sections.append("".join(current))
        cleaned_sections = [uncomment_source(section) for section in sections]
        for old, new in SAFE_CODE_FIXES.get(name, ()):
            cleaned_sections = [source.replace(old, new) for source in cleaned_sections]
        changed = len(cleaned_sections) != 1 or (cleaned_sections and cleaned_sections[0] != original)
        for part, source in enumerate(cleaned_sections, 1):
            if not source.strip():
                continue
            new_cell = copy.deepcopy(cell)
            new_cell["source"] = source.splitlines(keepends=True)
            if changed:
                old_id = new_cell.get("id", "cell")
                new_cell["id"] = (old_id[:52] + (f"_part{part}" if len(cleaned_sections) > 1 else "_clean"))[:64]
                new_cell["execution_count"] = None
                new_cell["outputs"] = []
            rebuilt.append(new_cell)
    nb["cells"] = rebuilt
    return nb

def read_notebook(practical):
    """Load a notebook from the script's embedded, compressed original JSON."""
    name = practical["notebook"]
    packed = EMBEDDED_NOTEBOOKS.get(name)
    path = ROOT / name
    if packed is None:
        return path, None, f"Notebook content is not embedded in this script: {name}"
    try:
        raw = zlib.decompress(base64.b85decode("".join(packed).encode("ascii")))
        nb = prepare_notebook(json.loads(raw.decode("utf-8")), name)
        return path, nb, None
    except (ValueError, zlib.error, UnicodeDecodeError, json.JSONDecodeError) as exc:
        return path, None, f"Embedded notebook content could not be decoded: {exc}"

def code_cells(nb):
    return [(number, "".join(c.get("source", []))) for number, c in enumerate((cell for cell in nb.get("cells", []) if cell.get("cell_type") == "code"))]

def print_answer(answer):
    """Render assistant text as wrapped, plain terminal bullets and sections."""
    width = shutil.get_terminal_size((80, 24)).columns
    width = max(44, min(width, 96))
    rule = "-" * width
    print("\n" + rule + "\nANSWER\n" + rule)
    for raw in str(answer).splitlines():
        line = raw.rstrip().replace("**", "").replace("`", "")
        if not line.strip():
            print()
            continue
        indent = len(line) - len(line.lstrip())
        content = line.lstrip()
        bullet = ""
        if content.startswith(("- ", "* ")):
            bullet, content = content[:2], content[2:]
        else:
            number = re.match(r"(\d+\.\s+)(.*)", content)
            if number:
                bullet, content = number.group(1), number.group(2)
        prefix = " " * indent + bullet
        subsequent = " " * (len(prefix) + 2)
        wrapped = textwrap.wrap(content, width=max(20, width-len(prefix)),
                                initial_indent=prefix, subsequent_indent=subsequent,
                                break_long_words=False, break_on_hyphens=False,
                                replace_whitespace=True, drop_whitespace=True)
        print("\n".join(wrapped) if wrapped else prefix.rstrip())
    print(rule)

def choose_practical():
    print("\nSelect a practical:")
    for i, p in enumerate(PRACTICALS, 1): print(f"{i}. {p['title']}")
    print("0. Back")
    while True:
        answer = input("Practical number: ").strip()
        if answer.casefold() in ("q", "quit", "exit"):
            global QUIT_REQUESTED
            QUIT_REQUESTED = True
            return None
        if answer == "0": return None
        if answer.isdigit() and 1 <= int(answer) <= len(PRACTICALS): return int(answer)-1
        print("Enter one of the listed numbers.")

